window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[191]={"id":"191","numero":191,"titre":"Fièvre chez l'immunodéprimé · Neutropénie fébrile","objectifs":[{"id":"191-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la neutropénie fébrile","contenu":"<p>La <span class=\"kw-def\">neutropénie</span> se définit sur la <span class=\"kw-bio\">numération formule sanguine</span> par un taux abaissé de <span class=\"kw-bio\">polynucléaires neutrophiles</span>. La fréquence et la gravité des infections sont proportionnelles à la <strong>profondeur</strong>, à la <strong>rapidité d'installation</strong> et à la <strong>durée</strong> de la neutropénie.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td>Neutropénie</td><td><span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&lt; 1,5 G/L</span> — dite <strong>sévère</strong> si <span class=\"kw-chiffre\">&lt; 0,5 G/L</span>, <strong>profonde</strong> si <span class=\"kw-chiffre\">&lt; 0,1 G/L</span>.</td></tr>\n          <tr><td>Neutropénie fébrile</td><td><span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&lt; 0,5 G/L</span> associé à une <span class=\"kw-clinique\">fièvre</span> : <span class=\"kw-chiffre\">T° ≥ 38,3 °C</span> en une prise, ou <span class=\"kw-chiffre\">≥ 38 °C</span> sur 2 prises à<span class=\"kw-chiffre\"> 1 h</span> d'intervalle. Une <span class=\"kw-alerte\">hypothermie</span> a la même valeur d'alerte.</td></tr>\n          <tr><td>Aplasie médullaire</td><td>Se définit sur une <span class=\"kw-bio\">étude de la moelle</span> (myélogramme, <span class=\"kw-bio\">biopsie</span> ostéo-médullaire), <span class=\"kw-alerte\">jamais sur la seule NFS</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ La neutropénie fébrile est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span> : contrairement aux autres situations d'immunodépression, l'<span class=\"kw-clinique\">évolution</span> se fait rapidement vers le <span class=\"kw-alerte\">choc septique</span>. Toute <span class=\"kw-clinique\">fièvre</span> aiguë chez l'immunodéprimé est <strong>infectieuse jusqu'à preuve du contraire</strong>.</div>\n      <p><strong>Variante ethnique :</strong> <span class=\"kw-clinique\">les</span> sujets d'origine africaine ont physiologiquement des <span class=\"kw-bio\">PNN</span> plus bas (jusqu'à <span class=\"kw-chiffre\">1 G/L</span>), par <span class=\"kw-def\">margination excessive</span> des PNN ; selon la source, ils restent exposés aux mêmes risques <span class=\"kw-etio\">infectieux</span> qu'une neutropénie sévère.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë · 190 — <span class=\"kw-clinique\">Fièvre</span> prolongée · 212 — <span class=\"kw-bio\">Hémogramme</span></em></p>","frequence":0},{"id":"191-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque des principales infections fongiques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">infections fongiques invasives</span> compliquent les neutropénies <strong>prolongées</strong>. Le <span class=\"kw-def\">facteur de risque</span> déterminant est la <strong>durée de la neutropénie</strong> : le risque <span class=\"kw-etio\">fongique</span> apparaît au-delà d'une <span class=\"kw-chiffre\">semaine</span> d'aplasie (<span class=\"kw-chiffre\">1 à 2 semaines</span>), et est majoré par sa <strong>profondeur</strong>.</p>\n      <table >\n        <thead><tr><th>Champignon</th><th><span class=\"kw-def\">Facteurs de risque</span> et présentation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Aspergillus</span>, <span class=\"kw-etio\">Mucorales</span></td><td>Contamination <strong>aérienne</strong>. Atteinte <span class=\"kw-clinique\">pulmonaire</span> et <span class=\"kw-clinique\">sinusienne</span>. Survient sur neutropénie <span class=\"kw-chiffre\">&gt; 7 jours</span> (<span class=\"kw-alerte\">aspergillose invasive</span>).</td></tr>\n          <tr><td><span class=\"kw-etio\">Candida</span> spp.</td><td>Candidose buccale quasi-systématique, <span class=\"kw-clinique\">colonisation digestive</span> fréquente. Risque de <span class=\"kw-alerte\">candidémie</span> et de localisations profondes sur <span class=\"kw-def\">terrain</span> à risque : <span class=\"kw-etio\">leucémie aiguë</span>, <strong>allogreffe de cellules souches hématopoïétiques</strong>.</td></tr>\n        </tbody>\n      </table>\n      <p>La prévention chez <span class=\"kw-clinique\">les</span> patients à risque repose sur l'<span class=\"kw-ttt\">isolement protecteur</span> en chambre à <span class=\"kw-def\">air</span> filtré (flux laminaire) dès une durée prévisible <span class=\"kw-chiffre\">&gt; 7 jours</span>, et sur un <span class=\"kw-ttt\">antifongique prophylactique</span> chez certains patients d'hématologie.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë</em></p>","frequence":0},{"id":"191-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de l’examen clinique en cas de neutropénie fébrile","contenu":"<p>Chez le neutropénique fébrile, la <span class=\"kw-clinique\">fièvre est souvent la seule manifestation</span> : le profond déficit en <span class=\"kw-bio\">PNN</span> empêche la formation de pus et atténue <span class=\"kw-clinique\">les</span> signes inflammatoires localisés. La <span class=\"kw-alerte\">gravité clinique est régulièrement sous-estimée</span>.</p>\n      <p><strong>Conséquence — des foyers <span class=\"kw-etio\">infectieux</span> trompeurs :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Pneumonie</span> :</strong> <span class=\"kw-clinique\">auscultation normale</span> et <span class=\"kw-imagerie\">radiographie de thorax normale chez 40 %</span> des neutropéniques.</li>\n        <li><strong><span class=\"kw-etio\">Méningite</span> :</strong> la <span class=\"kw-bio\">pléiocytose peut manquer</span> dans le <span class=\"kw-bio\">LCS</span>.</li>\n        <li><strong><span class=\"kw-etio\">Infection urinaire</span> :</strong> <span class=\"kw-bio\">leucocyturie souvent absente</span> à l'<span class=\"kw-bio\">ECBU</span>.</li>\n      </ul>\n      <p><strong>Lésions ulcéro-nécrotiques des muqueuses</strong> — en rapport direct avec le déficit en PNN : <span class=\"kw-alerte\">hyperalgiques</span>, <strong>creusantes</strong>, exposant à la <span class=\"kw-alerte\">surinfection</span>. Toutes <span class=\"kw-clinique\">les</span> muqueuses peuvent être touchées, mais la <span class=\"kw-clinique\">cavité buccale</span> est le siège le plus fréquent : l'<span class=\"kw-alerte\">angine ulcéro-nécrotique</span> est extrêmement évocatrice.</p>\n      <p>L'examen clinique doit être <strong>complet et répété</strong> (2 fois par jour), à la recherche systématique des trois portes d'entrée (digestive, cutanée, pulmonaire), de l'état des abords vasculaires et de <span class=\"kw-alerte\">signes de gravité</span> hémodynamiques.</p>","frequence":0},{"id":"191-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux agents pathogènes responsables d’infections en fonction du type de déficit immunitaire","contenu":"<p>Le <strong>type</strong>, la <strong>profondeur</strong> et la <strong>durée</strong> du déficit immunitaire déterminent <span class=\"kw-clinique\">les</span> agents pathogènes en cause. Dans la neutropénie fébrile, environ deux tiers des infections documentées sont à <strong>cocci Gram positif</strong> et un tiers à <strong>bacilles Gram négatif</strong>.</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Agents et caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td>Gram positif (2/3)</td><td><strong><span class=\"kw-etio\">Staphylocoque à coagulase négative</span></strong> : <span class=\"kw-etio\">le plus fréquent</span>, <span class=\"kw-clinique\">porte d'entrée</span> souvent par <span class=\"kw-clinique\">cathéter</span>, <span class=\"kw-clinique\">bactériémie</span> de <strong>bon <span class=\"kw-def\">pronostic</span></strong> (un retard d'ATB y est peu préjudiciable). <br><strong><span class=\"kw-etio\">S. aureus, streptocoques oraux, pneumocoque</span></strong> : à eux trois ~<span class=\"kw-chiffre\">15 %</span> des infections, <span class=\"kw-alerte\">rapidement évolutifs</span> — l'ATB probabiliste doit impérativement <span class=\"kw-clinique\">les</span> couvrir.</td></tr>\n          <tr><td>Gram négatif (1/3)</td><td><strong>Entérobactéries</strong> d'origine digestive ou urinaire : <span class=\"kw-etio\">E. coli</span>, <span class=\"kw-etio\">Klebsiella</span> spp. <br><span class=\"kw-alerte\">Pseudomonas aeruginosa</span> : <strong>1ʳᵉ cause de <span class=\"kw-def\">mortalité</span></strong> par infection chez le neutropénique, ~<span class=\"kw-chiffre\">5 %</span> des neutropénies fébriles, surtout dans <span class=\"kw-clinique\">les</span> neutropénies <span class=\"kw-chiffre\">&gt; 7 jours</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Fongique</span></td><td><span class=\"kw-etio\">Aspergillus</span> et <span class=\"kw-etio\">Mucorales</span> (aérien, pulmonaire et sinusien), <span class=\"kw-etio\">Candida</span> : neutropénie <span class=\"kw-chiffre\">&gt; 1 semaine</span>.</td></tr>\n          <tr><td><span class=\"kw-etio\">Viral</span></td><td><span class=\"kw-etio\">Herpes simplex virus (HSV)</span> : fréquent, précoce, associé à la <span class=\"kw-clinique\">mucite</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>Au-delà de la neutropénie, le germe attendu dépend du <strong>type de déficit immunitaire</strong> en cause — déficit <span class=\"kw-def\">humoral</span>, déficit <span class=\"kw-def\">cellulaire</span>, <span class=\"kw-def\">asplénie</span> — détaillé à l'objectif suivant. L'asplénie expose spécifiquement aux <span class=\"kw-etio\">bactéries encapsulées</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 201 — Transplantation d'organe</em></p>","frequence":4},{"id":"191-5","rang":"A","rubrique":"Physiopathologie","titre":"Citer les trois principales portes d’entrée de fièvre du neutropénique","contenu":"<p>Trois portes d'entrée dominent chez le neutropénique fébrile. Elles sont recherchées systématiquement, mais <strong>aucun foyer n'est retrouvé dans <span class=\"kw-chiffre\">60 %</span> des cas</strong> (le patient devient apyrétique sous ATB).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Porte d'entrée</span></th><th>Mécanisme et germes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Digestive</span></td><td><span class=\"kw-clinique\">Porte d'entrée</span> principale, par <strong><span class=\"kw-def\">translocation bactérienne</span></strong> : le <span class=\"kw-clinique\">tube digestif</span> est l'organe le plus colonisé, la <span class=\"kw-ttt\">chimiothérapie</span> lèse sa muqueuse (<span class=\"kw-clinique\">mucite</span>) et la neutropénie déséquilibre le microbiote. Germes : <span class=\"kw-etio\">entérobactéries (BGN)</span>, <span class=\"kw-etio\">entérocoque</span>, <span class=\"kw-etio\">anaérobies stricts</span>, <span class=\"kw-etio\">Candida</span> ; porte d'entrée buccale (<span class=\"kw-etio\">streptocoques</span>, groupe <span class=\"kw-etio\">HACEK</span>) favorisée par la <span class=\"kw-clinique\">mucite</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Cutanée</span></td><td>Attention aux <strong>abords vasculaires</strong> et <span class=\"kw-clinique\">cathéters veineux</span> : germes cutanés, notamment <span class=\"kw-etio\">staphylocoques</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Pulmonaire</span></td><td>À évoquer devant toute <span class=\"kw-clinique\">dyspnée</span> ou <span class=\"kw-clinique\">hypoxie</span>, <strong>y compris en l'absence de foyer à l'<span class=\"kw-clinique\">auscultation</span></strong>.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"191-6","rang":"A","rubrique":"Identifier une urgence","titre":"Reconnaître le caractère urgent de la prise en charge thérapeutique d’une neutropénie fébrile et d’un patient immunodéprimé fébrile","contenu":"<p>La neutropénie fébrile, comme toute <span class=\"kw-clinique\">fièvre</span> du patient immunodéprimé, est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span>. Elle est considérée comme <strong>infectieuse jusqu'à preuve du contraire</strong>.</p>\n      <table >\n        <thead><tr><th>Principe</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Délai</td><td><span class=\"kw-ttt\">Antibiothérapie</span> dans l'<span class=\"kw-alerte\">heure</span> qui suit, débutée après <span class=\"kw-clinique\">les</span> prélèvements (<span class=\"kw-bio\">hémocultures</span>) sans en attendre les résultats.</td></tr>\n          <tr><td>Probabilisme</td><td>ATB <strong><span class=\"kw-ttt\">bactéricide</span></strong>, débutée <span class=\"kw-alerte\">même sans certitude</span> d'une <span class=\"kw-etio\">infection bactérienne</span>.</td></tr>\n          <tr><td>Enjeu vital</td><td><span class=\"kw-def\">Mortalité</span> de <span class=\"kw-chiffre\">60 % à 24 h</span> pour une <span class=\"kw-alerte\">bactériémie</span> à <span class=\"kw-alerte\">Pseudomonas aeruginosa</span> non traitée chez le neutropénique.</td></tr>\n          <tr><td>Gravité</td><td>Rechercher <span class=\"kw-clinique\">les</span> signes de <span class=\"kw-alerte\">sepsis</span> et de <span class=\"kw-alerte\">choc septique</span> (<span class=\"kw-clinique\">troubles hémodynamiques</span>, <span class=\"kw-clinique\">neuropsychiques</span>, <span class=\"kw-clinique\">digestifs</span>) → orientation en <span class=\"kw-alerte\">USC / réanimation</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">signes cliniques</span> sont <strong>minorés</strong> chez l'immunodéprimé : la <span class=\"kw-alerte\">gravité réelle est sous-estimée</span> et l'<span class=\"kw-etio\">agent infectieux</span> se multiplie plus vite. Ne jamais banaliser une <span class=\"kw-clinique\">fièvre</span> isolée.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":1},{"id":"191-7","rang":"B","rubrique":"Etiologies","titre":"Citer les principaux agents infectieux responsables d’infection en fonction des situations d’immunodépression","contenu":"<p>Le germe en cause dépend de la <strong>situation d'immunodépression</strong>. On distingue <span class=\"kw-clinique\">les</span> déficits de l'immunité <span class=\"kw-def\">humorale</span> (<span class=\"kw-bio\">lymphocytes</span> B), <span class=\"kw-def\">cellulaire</span> (<span class=\"kw-bio\">lymphocytes</span> T) et de l'immunité <span class=\"kw-def\">innée</span> (dont la neutropénie), auxquels s'ajoutent l'asplénie et les déficits du <span class=\"kw-bio\">complément</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Causes et agents associés</th></tr></thead>\n        <tbody>\n          <tr><td>Déficit <span class=\"kw-def\">humoral</span></td><td>Hypogammaglobulinémie, déficit immunitaire commun variable, hémopathies lymphoïdes (<span class=\"kw-etio\">LLC</span>, myélome). Expose aux <span class=\"kw-etio\">bactéries encapsulées</span>.</td></tr>\n          <tr><td>Déficit <span class=\"kw-def\">cellulaire</span></td><td><span class=\"kw-etio\">VIH</span>, transplantation d'organe et greffe de moelle, <span class=\"kw-ttt\">corticothérapie</span> ou <span class=\"kw-ttt\">immunosuppresseur</span> prolongés, maladie de Hodgkin, maladies auto-immunes.</td></tr>\n          <tr><td><span class=\"kw-def\">Neutropénie</span> / immunité innée</td><td><span class=\"kw-ttt\">Chimiothérapie</span>, radiothérapie, agranulocytose médicamenteuse, aplasie médullaire, myélodysplasie (voir le tableau étiologique ci-dessous).</td></tr>\n          <tr><td><span class=\"kw-def\">Asplénie</span> / splénectomie</td><td>Déficit de phagocytose. Expose aux <span class=\"kw-etio\">bactéries encapsulées</span> et au <span class=\"kw-etio\">paludisme</span> grave (protozoaires intracellulaires).</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Étiologies de la neutropénie</strong> (<span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&lt; 1,5 G/L</span>) :</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td>Hématologiques</td><td>Insuffisance médullaire : <span class=\"kw-bio\">envahissement</span> médullaire, <span class=\"kw-etio\">syndrome myélodysplasique</span>, myélofibrose, aplasie médullaire idiopathique, carence en vitamines <span class=\"kw-bio\">B9 / B12</span>.</td></tr>\n          <tr><td>Médicaments, radiations</td><td><span class=\"kw-etio\">Agranulocytose médicamenteuse</span> (<span class=\"kw-etio\">toxique</span> ou immuno-allergique) ; <span class=\"kw-ttt\">chimiothérapie</span> ou radiothérapie : neutropénie <span class=\"kw-chiffre\">&lt; 7 jours</span> pour <span class=\"kw-clinique\">les</span> cancers solides, <span class=\"kw-chiffre\">&gt; 7 jours</span> pour les hémopathies.</td></tr>\n          <tr><td>Infectieuses</td><td>Bactéries (<span class=\"kw-etio\">typhoïde</span>, brucellose, bactériémies graves), virus (<span class=\"kw-etio\">VIH</span>, hépatites, rougeole, <span class=\"kw-etio\">grippe</span>, dengue), parasites (<span class=\"kw-etio\">paludisme</span>, leishmaniose).</td></tr>\n          <tr><td>Dysimmunitaires</td><td>Connectivites : <span class=\"kw-etio\">lupus</span>, <span class=\"kw-clinique\">Gougerot-Sjögren</span>, <span class=\"kw-clinique\">syndrome de Felty</span> ; <span class=\"kw-alerte\">syndrome d'activation macrophagique</span>.</td></tr>\n          <tr><td>Autres</td><td>Séquestration splénique (hypersplénisme), maladies de surcharge (Gaucher), causes congénitales, excès de margination (ethnique ou non).</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 170 — <span class=\"kw-clinique\">Paludisme</span> · 201 — Transplantation d'organe</em></p>","frequence":0},{"id":"191-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à effectuer chez le neutropénique fébrile en fonction de l’orientation clinique","contenu":"<p>Le bilan est <strong>orienté</strong> par la clinique, mais un socle d'examens est systématique. Il doit être réalisé <span class=\"kw-alerte\">sans retarder l'antibiothérapie</span>.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Biologie</td><td><span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">créatinine-urée</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">bilan d'hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>), <span class=\"kw-bio\">procalcitonine</span>, <span class=\"kw-bio\">gaz du sang avec lactates</span> artériels.</td></tr>\n          <tr><td>Microbiologie</td><td><span class=\"kw-bio\">Hémocultures</span> : 2 séries à<span class=\"kw-chiffre\"> 30 min</span> d'intervalle, <strong>avant toute ATB</strong> (positives dans <span class=\"kw-chiffre\">20-30 %</span> des cas) ; si VVC, <span class=\"kw-bio\">hémocultures</span> <strong>couplées</strong> simultanées en périphérie et sur le cathéter (délai différentiel de positivité). <span class=\"kw-bio\">BU + ECBU</span> (même sans <span class=\"kw-bio\">leucocyturie</span>). <span class=\"kw-bio\">Coproculture</span> et recherche de <span class=\"kw-etio\">Clostridioides difficile</span> selon le contexte. Prélèvements ciblés (gorge, etc.) sur points d'appel.</td></tr>\n          <tr><td>Imagerie</td><td><span class=\"kw-imagerie\">Radiographie de thorax</span> systématique, mais <span class=\"kw-alerte\">peu sensible</span> en neutropénie. <span class=\"kw-imagerie\">TDM thoracique</span> si neutropénie <span class=\"kw-chiffre\">&gt; 1 semaine</span> ou en présence de signes respiratoires ou abdominaux.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ Piège classique : la <span class=\"kw-bio\">CRP</span> n'est <strong>pas un critère fiable</strong> chez le neutropénique fébrile — elle peut être normale au début. La retenir comme marqueur décisif est <span class=\"kw-alerte\">FAUX</span> (« <span class=\"kw-bio\">CRP</span> cochée faux »).</div>\n      <p><strong>Si neutropénie &gt;<span class=\"kw-chiffre\"> 7 jours</span></strong> (risque <span class=\"kw-etio\">fongique</span> surajouté), compléter par : <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> et <span class=\"kw-imagerie\">TDM des sinus</span>, <span class=\"kw-imagerie\">échographie cardiaque (ETT)</span>, <span class=\"kw-imagerie\">échodoppler veineux</span>, <span class=\"kw-bio\">antigénémie aspergillaire</span> ± <span class=\"kw-bio\">LBA</span> par <span class=\"kw-imagerie\">fibroscopie</span> bronchique.</p>","frequence":1},{"id":"191-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement antibiotique de la neutropénie fébrile, en fonction de sa profondeur","contenu":"<p>L'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste est <strong>précoce</strong> (après prélèvements), <strong>bactéricide</strong> et adaptée au <strong>niveau de risque</strong>. Une <span class=\"kw-alerte\">réévaluation systématique à 48-72 h</span> est impérative.</p>\n      <table >\n        <thead><tr><th></th><th>Faible risque</th><th>Haut risque</th></tr></thead>\n        <tbody>\n          <tr><td>Critères</td><td><span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 0,1 G/L</span>, durée prévisible <span class=\"kw-chiffre\">&lt; 7 jours</span>, pas de <span class=\"kw-alerte\">signe de gravité</span>, patient autonome, pas d'ATCD à risque, pas d'<span class=\"kw-ci\">intolérance</span> digestive.</td><td>Absence des <span class=\"kw-def\">critères de</span> faible risque, <strong>ou</strong> persistance de la <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&gt; 24-48 h</span>.</td></tr>\n          <tr><td>Orientation</td><td><strong>Ambulatoire</strong>.</td><td><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">isolement protecteur</span> ; chambre à <span class=\"kw-def\">air</span> stérile (flux laminaire) si durée <span class=\"kw-chiffre\">&gt; 7 jours</span>, du fait du risque <span class=\"kw-etio\">fongique</span> surajouté (aspergillose invasive, candidose).</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibiothérapie</span></td><td>Voie orale : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">ciprofloxacine</span>.</td><td><span class=\"kw-ttt\">β-lactamine anti-Pseudomonas</span> systématique : <span class=\"kw-ttt\">pipéracilline-tazobactam</span>, <span class=\"kw-ttt\">céfépime</span>, <span class=\"kw-ttt\">ceftazidime</span> ou <span class=\"kw-ttt\">carbapénème</span>. <br>+ <span class=\"kw-ttt\">vancomycine</span> si infection de cathéter ou cutanée, <span class=\"kw-etio\">colonisation</span> à <span class=\"kw-bio\">SARM</span>, ou persistance de la <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&gt; 72 h</span>. <br>+ <span class=\"kw-ttt\">amikacine</span> si suspicion de <span class=\"kw-etio\">BMR</span> ou <span class=\"kw-def\">sepsis</span> / <span class=\"kw-def\">choc septique</span>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Durée :</strong> l'ATB est maintenue <strong>toute la durée de la neutropénie</strong> (objectif <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 0,5 G/L</span>). Arrêt possible si <span class=\"kw-chiffre\">48 h d'apyrexie</span> + correction de la neutropénie + aucun pathogène ni foyer identifié. Si une infection est documentée, la durée est celle d'un patient non neutropénique.</p>\n      <p><strong>Persistance de la <span class=\"kw-clinique\">fièvre</span> &gt;<span class=\"kw-chiffre\"> 7 jours</span> :</strong> ajout systématique d'un <span class=\"kw-ttt\">antifongique probabiliste</span> et bilan du risque <span class=\"kw-etio\">fongique</span> invasif (<span class=\"kw-imagerie\">TDM</span> thoracique et des sinus, <span class=\"kw-bio\">antigénémie</span> aspergillaire, ± <span class=\"kw-bio\">LBA</span>).</p>\n      <div class=\"callout callout-info\">📌 Mesures associées : <span class=\"kw-ttt\">bains de bouche</span> systématiques (prévention des mucites) ; <span class=\"kw-ttt\">G-CSF</span> dans certaines situations (neutropénie prolongée, infection des parties molles — réduit la durée de neutropénie d'environ <span class=\"kw-chiffre\">48 h</span>). Pas d'<span class=\"kw-ttt\">antibioprophylaxie</span> systématique.</div>\n      <p><strong>Conditions requises pour une prise en charge ambulatoire</strong> — tous <span class=\"kw-clinique\">les</span> critères doivent être réunis :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Condition</th></tr></thead>\n        <tbody>\n          <tr><td>Âge</td><td><span class=\"kw-chiffre\">&lt; 65 ans</span></td></tr>\n          <tr><td>Durée de neutropénie</td><td>Attendue brève, <span class=\"kw-chiffre\">&lt; 8 jours</span></td></tr>\n          <tr><td>Taux de PNN</td><td><span class=\"kw-chiffre\">&gt; 100/mm³</span> (PNN et <span class=\"kw-bio\">monocytes</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Signes de gravité</span></td><td>Absents</td></tr>\n          <tr><td>Foyer <span class=\"kw-etio\">infectieux</span></td><td>Aucun foyer documenté, notamment pulmonaire ou cutané</td></tr>\n          <tr><td><span class=\"kw-def\">Comorbidités</span></td><td>Absentes</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibiothérapie</span></td><td>Pas d'<span class=\"kw-ttt\">antibiothérapie</span> récente</td></tr>\n          <tr><td>Accompagnement</td><td>Présence d'un accompagnant à domicile</td></tr>\n          <tr><td><span class=\"kw-def\">Suivi</span> médical</td><td><span class=\"kw-def\">Contact</span> possible à tout moment avec un médecin spécialiste référent</td></tr>\n          <tr><td>Compréhension</td><td>Bonne compréhension du patient</td></tr>\n        </tbody>\n      </table>","frequence":4},{"id":"191-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes de la prévention du risque infecieux chez l’asplénique et le traitement d’urgence de l’asplénique fébrile","contenu":"<p>L'<span class=\"kw-def\">asplénie</span> — anatomique après splénectomie, ou fonctionnelle (drépanocytose) — entraîne un <strong>déficit de phagocytose</strong>. Elle expose au risque d'<span class=\"kw-alerte\">infection fulminante du splénectomisé (OPSI</span>, <em>overwhelming post-splenectomy infection</em><span class=\"kw-alerte\">)</span>.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Risque</td><td>Bactériémies <span class=\"kw-alerte\">foudroyantes</span> à <span class=\"kw-etio\">bactéries encapsulées</span> (<span class=\"kw-chiffre\">95 %</span> de <span class=\"kw-etio\">pneumocoque</span>). Gravité majorée en cas d'infection à protozoaires intracellulaires (<span class=\"kw-etio\">Plasmodium</span>).</td></tr>\n          <tr><td>Prévention vaccinale</td><td>Vaccins <strong>conjugués</strong> : <span class=\"kw-ttt\">pneumocoque</span>, <span class=\"kw-ttt\">Haemophilus influenzae b</span>, <span class=\"kw-ttt\">méningocoque</span> ; + <span class=\"kw-ttt\">vaccination</span> <span class=\"kw-ttt\">antigrippale</span> annuelle.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibioprophylaxie</span></td><td><span class=\"kw-ttt\">Pénicilline V</span> orale, généralement <span class=\"kw-chiffre\">2 ans</span> après la splénectomie chez l'adulte.</td></tr>\n          <tr><td>Éducation</td><td>Le patient asplénique doit savoir <strong>prendre de l'<span class=\"kw-ttt\">amoxicilline</span> devant toute <span class=\"kw-clinique\">fièvre</span> brutale, avant même d'appeler le médecin</strong> ; port d'une carte de splénectomisé.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Asplénique fébrile = <span class=\"kw-alerte\">urgence</span>.</strong> Devant toute <span class=\"kw-clinique\">fièvre</span> inexpliquée : <span class=\"kw-ttt\">antibiothérapie probabiliste IV urgente</span> active sur <span class=\"kw-clinique\">les</span> bactéries encapsulées — <span class=\"kw-ttt\">C3G IV (céfotaxime ou ceftriaxone)</span> — débutée juste après les <span class=\"kw-bio\">hémocultures</span>. La <span class=\"kw-ttt\">vaccination</span> anti-pneumococcique <strong>ne supprime pas</strong> le risque sur ce <span class=\"kw-def\">terrain</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":1},{"id":"191-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications et contre-indications vaccinales chez l’immunodéprimé","contenu":"<p>Chez l'immunodéprimé, le <strong><span class=\"kw-ttt\">calendrier vaccinal</span> général s'applique</strong>, à une exception majeure près : <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">vaccins vivants atténués</span>.</p>\n      <table >\n        <thead><tr><th>Type de vaccin</th><th>Règle chez l'immunodéprimé</th></tr></thead>\n        <tbody>\n          <tr><td>Vaccins <span class=\"kw-def\">inactivés</span></td><td><strong>Autorisés</strong> — le <span class=\"kw-ttt\">calendrier vaccinal</span> général est conservé. Plusieurs vaccinations sont même <strong>renforcées</strong> selon le <span class=\"kw-def\">terrain</span> (voir ci-dessous).</td></tr>\n          <tr><td>Vaccins <span class=\"kw-def\">vivants atténués</span></td><td><span class=\"kw-ci\">Contre-indiqués</span> : <span class=\"kw-ci\">ROR</span>, <span class=\"kw-ci\">poliomyélite orale</span>, <span class=\"kw-ci\">fièvre jaune</span>, <span class=\"kw-ci\">varicelle</span>, <span class=\"kw-ci\">BCG</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Exception : <strong>après splénectomie</strong>, aucun <span class=\"kw-def\">vaccin vivant</span> n'est <span class=\"kw-ci\">contre-indiqué</span> (l'<span class=\"kw-def\">asplénie</span> n'altère pas l'immunité antivirale). Penser aussi à <strong>vacciner l'entourage</strong> du patient immunodéprimé.</div>\n      <p><strong>Vaccinations spécifiques renforcées</strong> selon le <span class=\"kw-def\">terrain</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Pneumocoque</span> :</strong> <span class=\"kw-def\">asplénie</span> ou splénectomie, <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-def\">syndrome néphrotique</span>, <span class=\"kw-def\">cirrhose</span>, <span class=\"kw-etio\">VIH</span>, déficit immunitaire <span class=\"kw-etio\">héréditaire</span>, <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">immunosuppresseur</span>, <span class=\"kw-ttt\">corticoïde</span>, transplantation d'organe ou greffe de cellules souches hématopoïétiques.</li>\n        <li><strong><span class=\"kw-ttt\">Méningocoque</span> :</strong> déficits du <span class=\"kw-bio\">complément</span>, <span class=\"kw-def\">asplénie</span> ou splénectomie, <span class=\"kw-etio\">drépanocytose</span>, greffe de CSH.</li>\n        <li><strong><span class=\"kw-ttt\">Haemophilus influenzae b</span> :</strong> <span class=\"kw-def\">asplénie</span> ou splénectomie, <span class=\"kw-etio\">drépanocytose</span>, greffe de CSH, déficit de l'immunité humorale.</li>\n        <li><strong><span class=\"kw-ttt\">Grippe</span></strong> annuelle, et <strong><span class=\"kw-ttt\">hépatites A et B</span></strong> (<span class=\"kw-etio\">VIH</span>, transplantation solide, <span class=\"kw-etio\">drépanocytose</span>).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Neutropénie fébrile <span class=\"q\">— infectieuse jusqu'à preuve du contraire</span></strong></p><p>Rechercher <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span> → orientation <span class=\"kw-alerte\">USC / réanimation</span></p><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste <span class=\"kw-alerte\">dans l'heure</span>, après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> et sans en attendre les résultats</li><li>ATB <span class=\"kw-ttt\">bactéricide</span> débutée <span class=\"kw-alerte\">même sans certitude</span> d'une <span class=\"kw-etio\">infection bactérienne</span></li><li>Enjeu vital : <span class=\"kw-alerte\">mortalité 60 % à 24 h</span> d'une <span class=\"kw-alerte\">bactériémie à Pseudomonas aeruginosa</span> non traitée</li></ul><p><strong>Asplénique fébrile <span class=\"q\">— risque d'OPSI</span></strong></p><p>La <span class=\"kw-ttt\">vaccination anti-pneumococcique</span> ne supprime pas le risque sur ce <span class=\"kw-def\">terrain</span></p><ul><li>Toute <span class=\"kw-clinique\">fièvre</span> brutale = <span class=\"kw-alerte\">urgence</span> (risque d'<span class=\"kw-alerte\">infection fulminante du splénectomisé</span>)</li><li><span class=\"kw-ttt\">Antibiothérapie IV</span> active sur <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">bactéries encapsulées</span> — <span class=\"kw-ttt\">C3G IV (céfotaxime ou ceftriaxone)</span> — juste après les <span class=\"kw-bio\">hémocultures</span></li></ul>","hospit":"<p><strong>Faible risque :</strong> <span class=\"kw-ttt\">ambulatoire</span> possible si TOUS <span class=\"kw-clinique\">les</span> critères sont réunis (<span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 0,1 G/L</span>, durée prévisible <span class=\"kw-chiffre\">&lt; 7 jours</span>, <span class=\"kw-chiffre\">âge &lt; 65 ans</span>, pas de gravité ni de foyer, accompagnant à domicile + <span class=\"kw-def\">suivi</span> spécialiste joignable).<br><strong>Haut risque :</strong> <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">isolement protecteur</span> ; chambre à <span class=\"kw-ttt\">air stérile (flux laminaire)</span> si durée <span class=\"kw-chiffre\">&gt; 7 jours</span> (risque <span class=\"kw-etio\">fongique</span> surajouté).<br><strong><span class=\"kw-clinique\">Sepsis</span> / <span class=\"kw-alerte\">choc</span> :</strong> <span class=\"kw-alerte\">USC / réanimation</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Sepsis</span> / <span class=\"kw-alerte\">choc septique</span> : <span class=\"kw-clinique\">troubles hémodynamiques</span>, <span class=\"kw-clinique\">neuropsychiques</span>, <span class=\"kw-clinique\">digestifs</span></li><li><span class=\"kw-alerte\">Hypothermie</span> — même valeur d'alerte que la <span class=\"kw-clinique\">fièvre</span></li><li><span class=\"kw-alerte\">Angine ulcéro-nécrotique</span> et lésions <span class=\"kw-clinique\">ulcéro-nécrotiques</span> des muqueuses (<span class=\"kw-alerte\">hyperalgiques</span>, creusantes)</li><li><span class=\"kw-clinique\">Dyspnée</span> ou <span class=\"kw-clinique\">hypoxie</span> même sans foyer à l'<span class=\"kw-clinique\">auscultation</span> (pneumonie à <span class=\"kw-imagerie\">RXT normale chez 40 %</span>)</li><li>Neutropénie <span class=\"kw-alerte\">profonde</span> (<span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&lt; 0,1 G/L</span>) et/ou <span class=\"kw-alerte\">prolongée &gt; 7 jours</span> (risque <span class=\"kw-etio\">Pseudomonas</span> et <span class=\"kw-etio\">fongique</span>)</li><li>Rappel : <span class=\"kw-alerte\">signes inflammatoires minorés</span> — la gravité réelle est sous-estimée</li></ul>","principes":"<p>ATB probabiliste <span class=\"kw-ttt\">précoce</span> (après prélèvements), <span class=\"kw-ttt\">bactéricide</span>, adaptée au <span class=\"kw-def\">niveau de risque</span>, avec <span class=\"kw-alerte\">réévaluation systématique à 48–72 h</span> ; maintenue toute la durée de la neutropénie (objectif <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 0,5 G/L</span>).</p><p><strong>Faible risque</strong></p><p>Prise en charge <span class=\"kw-ttt\">ambulatoire</span></p><ul><li>Voie orale : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">ciprofloxacine</span></li></ul><p><strong>Haut risque</strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">isolement protecteur</span></p><ul><li><span class=\"kw-ttt\">β-lactamine anti-Pseudomonas</span> systématique : <span class=\"kw-ttt\">pipéracilline-tazobactam</span>, <span class=\"kw-ttt\">céfépime</span>, <span class=\"kw-ttt\">ceftazidime</span> ou <span class=\"kw-ttt\">carbapénème</span></li><li>+ <span class=\"kw-ttt\">vancomycine</span> si infection de cathéter / cutanée, <span class=\"kw-etio\">colonisation</span> à <span class=\"kw-etio\">SARM</span>, ou <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&gt; 72 h</span></li><li>+ <span class=\"kw-ttt\">amikacine</span> si suspicion de <span class=\"kw-etio\">BMR</span> ou <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span></li></ul><p><strong>Persistance de la <span class=\"kw-clinique\">fièvre</span> <span class=\"q\">— &gt;<span class=\"kw-chiffre\"> 7 jours</span></span></strong></p><p>Rechercher aussi <span class=\"kw-etio\">endocardite</span> (<span class=\"kw-imagerie\">ETT</span>) et <span class=\"kw-etio\">thrombophlébite septique</span> (<span class=\"kw-imagerie\">échodoppler veineux</span>)</p><ul><li>Ajout systématique d'un <span class=\"kw-ttt\">antifongique probabiliste</span></li><li>Bilan <span class=\"kw-etio\">fongique</span> invasif : <span class=\"kw-imagerie\">TDM thoracique et des sinus</span>, <span class=\"kw-bio\">antigénémie aspergillaire</span> ± <span class=\"kw-bio\">LBA</span></li></ul><p><strong>Mesures associées</strong></p><p>Pas d'<span class=\"kw-ttt\">antibioprophylaxie</span> systématique</p><ul><li><span class=\"kw-ttt\">Bains de bouche</span> systématiques (prévention des mucites)</li><li><span class=\"kw-ttt\">G-CSF</span> dans certaines situations (neutropénie prolongée, infection des parties molles — réduit la durée d'environ <span class=\"kw-chiffre\">48 h</span>)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span> :</strong> systématique à <span class=\"kw-chiffre\">48–72 h</span> ; <span class=\"kw-clinique\">fièvre</span> persistante <span class=\"kw-chiffre\">&gt; 24–48 h</span> = reclassement en haut risque.<br><strong>Arrêt de l'ATB :</strong> possible si <span class=\"kw-chiffre\">48 h d'apyrexie</span> + correction de la neutropénie + aucun pathogène ni foyer identifié ; si infection documentée, durée comme un patient non neutropénique.<br><strong>Examen clinique :</strong> complet et <span class=\"kw-alerte\">répété 2×/jour</span> (portes d'entrée digestive, cutanée, pulmonaire ; abords vasculaires).<br><strong>Piège :</strong> la <span class=\"kw-bio\">CRP</span> n'est pas un critère fiable chez le neutropénique fébrile (peut être normale au début).</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-191.pdf","label":"Pilly étudiant — Pilly 2023 item 191"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Neutropénie fébrile : stratification du risque — Urgence : hémocultures puis antibiothérapie dans l'heure","detail":"<h4>CAT — neutropénie fébrile : stratification du risque — Tri <span class=\"kw-alerte\">urgence</span> → faible <span class=\"kw-bio\">vs</span> haut risque → risque <span class=\"kw-etio\">fongique</span></h4>","branches":[{"to":"t-grave","label":"Sepsis / choc septique","color":"red"},{"to":"q-risque","label":"Pas de signe de gravité","color":"blue"}]},{"id":"t-grave","kind":"terminal","label":"Haut risque d'emblée → réanimation","color":"red","detail":"<h4>Conduite</h4><ul><li>ATB <span class=\"kw-ttt\">large spectre</span> en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-ttt\">β-lactamine anti-Pseudomonas</span> + <span class=\"kw-ttt\">amikacine</span> + <span class=\"kw-ttt\">vancomycine</span></li></ul><h4>Orientation</h4><ul><li>Transfert en <span class=\"kw-alerte\">USC / réanimation</span> ; <span class=\"kw-ttt\">remplissage</span> et <span class=\"kw-clinique\">monitorage</span></li></ul><h4>Délai</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> dans l'<span class=\"kw-alerte\">heure</span>, après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> (couplées périphérie + cathéter si VVC)</li></ul><h4>Renvoi</h4><ul><li>Item 158 (<span class=\"kw-alerte\">sepsis</span> et <span class=\"kw-alerte\">choc septique</span>)</li></ul>"},{"id":"q-risque","kind":"decision","label":"<span class=\"kw-def\">Critères de</span> faible risque tous réunis ? — PNN <span class=\"kw-chiffre\">> 0,</span><span class=\"kw-chiffre\">1 G/L</span> · durée prévisible < 7 j · âge < 65 ans · autonome · pas d'ATCD à risque · pas d'<span class=\"kw-ci\">intolérance</span> digestive","branches":[{"to":"t-faible","label":"Oui — tous réunis","color":"green"},{"to":"q-duree","label":"Non — au moins un critère manquant","color":"amber"}]},{"id":"t-faible","kind":"terminal","label":"Faible risque → ambulatoire","color":"green","detail":"<h4>Critères</h4><ul><li><span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 0,1 G/L</span> ; durée prévisible <span class=\"kw-chiffre\">&lt; 7 j</span> ; <span class=\"kw-chiffre\">âge &lt; 65 ans</span> ; pas de gravité ni de foyer documenté ; accompagnant à domicile ; <span class=\"kw-def\">suivi</span> spécialiste joignable</li></ul><h4>Traitement</h4><ul><li>Voie orale : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> + <span class=\"kw-ttt\">ciprofloxacine</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">48–72 h</span> ; <span class=\"kw-clinique\">fièvre</span> persistante <span class=\"kw-chiffre\">&gt; 24–48 h</span> → reclassement en haut risque</li></ul>"},{"id":"q-duree","kind":"decision","label":"Neutropénie / fièvre persistante > 7 jours ? — Au-delà de 7 jours, le risque fongique invasif se surajoute","branches":[{"to":"t-haut","label":"Non (< 7 jours)","color":"amber"},{"to":"t-fongique","label":"Oui (> 7 j) ou fièvre persistante","color":"red"}]},{"id":"t-haut","kind":"terminal","label":"Haut risque → hospitalisation","color":"amber","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">isolement protecteur</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">β-lactamine anti-Pseudomonas</span> (<span class=\"kw-ttt\">pipéracilline-tazobactam</span>, <span class=\"kw-ttt\">céfépime</span>, <span class=\"kw-ttt\">ceftazidime</span> ou <span class=\"kw-ttt\">carbapénème</span>) ; + <span class=\"kw-ttt\">vancomycine</span> si cathéter / cutané / <span class=\"kw-etio\">SARM</span> ou <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&gt; 72 h</span> ; + <span class=\"kw-ttt\">amikacine</span> si <span class=\"kw-etio\">BMR</span></li></ul><h4>Mesures associées</h4><ul><li><span class=\"kw-ttt\">Bains de bouche</span> ; <span class=\"kw-ttt\">G-CSF</span> selon la situation (neutropénie prolongée, infection des parties molles)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">48–72 h</span> ; ATB maintenue jusqu'à <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">&gt; 0,5 G/L</span></li></ul>"},{"id":"t-fongique","kind":"terminal","label":"Risque fongique invasif → antifongique","color":"red","detail":"<h4>Conduite</h4><ul><li>Ajout systématique d'un <span class=\"kw-ttt\">antifongique probabiliste</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-imagerie\">TDM thoracique et des sinus</span>, <span class=\"kw-bio\">antigénémie aspergillaire</span> ± <span class=\"kw-bio\">LBA</span> par <span class=\"kw-imagerie\">fibroscopie</span> bronchique</li></ul><h4>À rechercher</h4><ul><li><span class=\"kw-etio\">Aspergillose invasive</span> et candidose ; <span class=\"kw-etio\">endocardite</span> (<span class=\"kw-imagerie\">ETT</span>) ; <span class=\"kw-etio\">thrombophlébite septique</span> (<span class=\"kw-imagerie\">échodoppler veineux</span>)</li></ul><h4>Prévention</h4><ul><li>Chambre à <span class=\"kw-ttt\">air stérile (flux laminaire)</span> si durée prévisible <span class=\"kw-chiffre\">&gt; 7 j</span></li></ul>"}]},"cards":[{"i":"235b01929ebf","n":191,"o":"191-1","u":"Définition","t":"Connaître la définition de la neutropénie fébrile","q":"Comment définit-on la neutropénie fébrile sur le plan biologique et clinique ?","a":"<p>La neutropénie fébrile est définie par une numération des polynucléaires neutrophiles (PNN) <strong>inférieure à 0,5 G/L</strong>, associée à une fièvre. La fièvre est définie par une <strong>température ≥ 38,3 °C</strong> en une prise, ou <strong>≥ 38 °C sur deux prises à 1 heure d'intervalle</strong>. Une hypothermie a la même valeur d'alerte.</p>"},{"i":"baa373dd62b2","n":191,"o":"191-1","u":"Définition","t":"Connaître la définition de la neutropénie fébrile","q":"Quelle définition de la neutropénie dans un contexte général et ses seuils de gravité ?","a":"<p>La neutropénie est définie par un taux abaissé de polynucléaires neutrophiles (PNN) <strong>inférieur à 1,5 G/L</strong> sur la numération formule sanguine. Elle est dite <strong>sévère si PNN &lt; 0,5 G/L</strong> et <strong>profonde si PNN &lt; 0,1 G/L</strong>.</p>"},{"i":"fafb566f1a56","n":191,"o":"191-1","u":"Définition","t":"Connaître la définition de la neutropénie fébrile","q":"Quelle est l'importance de la neutropénie fébrile en médecine d'urgence ?","a":"<p>La neutropénie fébrile constitue une <strong>urgence diagnostique et thérapeutique absolue</strong>. Contrairement à d'autres situations d'immunodépression, son évolution peut être très rapide vers le <strong>choc septique</strong>.</p>"},{"i":"0768467aaa52","n":191,"o":"191-3","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’examen clinique en cas de neutropénie fébrile","q":"Quelles sont les particularités de l'examen clinique des foyers infectieux chez le patient neutropénique fébrile ?","a":"<ul><li><strong>Pneumonie</strong> : l'auscultation et la radiographie thoracique peuvent être normales dans <strong>40 %</strong> des cas.</li><li><strong>Méningite</strong> : la pléiocytose peut être absente dans le liquide céphalorachidien (LCS).</li><li><strong>Infection urinaire</strong> : la leucocyturie est souvent absente à l'examen cytobactériologique des urines (ECBU).</li></ul>"},{"i":"8974dbc8731e","n":191,"o":"191-3","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’examen clinique en cas de neutropénie fébrile","q":"Quelles sont les lésions des muqueuses spécifiques à rechercher en cas de neutropénie fébrile ?","a":"<p>Il faut rechercher des <strong>lésions ulcéro-nécrotiques des muqueuses</strong>. Elles sont hyperalgiques, creusantes et exposent à la surinfection. Toutes les muqueuses peuvent être touchées, mais la cavité buccale est le site le plus fréquent, et l'<strong>angine ulcéro-nécrotique</strong> est très évocatrice.</p>"},{"i":"b56b08551102","n":191,"o":"191-3","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’examen clinique en cas de neutropénie fébrile","q":"Quelle est la principale caractéristique clinique de la neutropénie fébrile et pourquoi ?","a":"<p>La <strong>fièvre</strong> est souvent la seule manifestation clinique chez le patient neutropénique fébrile. Ceci est dû au profond déficit en <strong>polynucléaires neutrophiles</strong> (PNN) qui empêche la formation de pus et atténue les signes inflammatoires localisés.</p>"},{"i":"cf663f93d467","n":191,"o":"191-3","u":"Diagnostic positif","t":"Connaître les caractéristiques de l’examen clinique en cas de neutropénie fébrile","q":"Comment doit être mené l'examen clinique chez un patient neutropénique fébrile et que doit-il rechercher spécifiquement ?","a":"<p>L'examen clinique doit être <strong>complet et répété</strong> (<strong>deux fois par jour</strong>). Il doit systématiquement rechercher les <strong>trois portes d'entrée</strong> (digestive, cutanée, pulmonaire), évaluer l'état des <strong>abords vasculaires</strong> et rechercher des <strong>signes de gravité hémodynamiques</strong>.</p>"},{"i":"6074a3f3ad1d","n":191,"o":"191-5","u":"Physiopathologie","t":"Citer les trois principales portes d’entrée de fièvre du neutropénique","q":"Quelle est la principale porte d'entrée de la fièvre chez le patient neutropénique fébrile ?","a":"<p>La principale porte d'entrée est <strong>digestive</strong>.</p>"},{"i":"9c7addd72d95","n":191,"o":"191-5","u":"Physiopathologie","t":"Citer les trois principales portes d’entrée de fièvre du neutropénique","q":"Quelles sont les autres portes d'entrée importantes de la fièvre chez le patient neutropénique fébrile ?","a":"<p>Outre la porte d'entrée digestive, les autres portes d'entrée importantes sont :</p><ul><li><strong>Cutanée</strong> (attention aux abords vasculaires et cathéters veineux)</li><li><strong>Pulmonaire</strong> (à évoquer devant toute dyspnée ou hypoxie)</li></ul>"},{"i":"d96b6184051d","n":191,"o":"191-5","u":"Physiopathologie","t":"Citer les trois principales portes d’entrée de fièvre du neutropénique","q":"Quels sont les germes les plus fréquemment en cause pour la porte d'entrée digestive et buccale chez le neutropénique fébrile ?","a":"<ul><li>Pour la porte d'entrée digestive : <strong>entérobactéries (BGN)</strong>, <strong>entérocoques</strong>, <strong>anaérobies stricts</strong>, <strong>Candida</strong>.</li><li>Pour la porte d'entrée buccale (favorisée par la mucite) : <strong>streptocoques</strong>, groupe <strong>HACEK</strong>.</li></ul>"},{"i":"e3b962e7ab92","n":191,"o":"191-5","u":"Physiopathologie","t":"Citer les trois principales portes d’entrée de fièvre du neutropénique","q":"Quel type de germe doit faire suspecter une porte d'entrée cutanée de la fièvre chez le neutropénique fébrile avec abord vasculaire ?","a":"<p>Les <strong>germes cutanés</strong>, notamment les <strong>staphylocoques</strong>, doivent faire suspecter une porte d'entrée cutanée.</p>"},{"i":"f44e42ee160f","n":191,"o":"191-5","u":"Physiopathologie","t":"Citer les trois principales portes d’entrée de fièvre du neutropénique","q":"Comment la porte d'entrée digestive favorise-t-elle la fièvre chez le patient neutropénique ?","a":"<p>Elle est favorisée par la <strong>translocation bactérienne</strong>, car le tube digestif est colonisé, la chimiothérapie lèse sa muqueuse (responsable de <strong>mucite</strong>) et la neutropénie déséquilibre le microbiote.</p>"},{"i":"9b319964c15c","n":191,"o":"191-6","u":"Identifier une urgence","t":"Reconnaître le caractère urgent de la prise en charge thérapeutique d’une neutropénie fébrile et d’un patient immunodéprimé fébrile","q":"Quelles sont les particularités des signes cliniques de gravité chez le patient immunodéprimé fébrile ?","a":"<p>Chez le patient immunodéprimé fébrile, les <strong>signes cliniques de gravité sont minorés</strong>. Cela signifie que la gravité réelle peut être <strong>sous-estimée</strong> et que l'agent infectieux se multiplie plus rapidement. Il est donc crucial de toujours rechercher activement les signes de sepsis et de choc septique (troubles hémodynamiques, neuropsychiques, digestifs) et de ne jamais banaliser une fièvre isolée.</p>"},{"i":"a0dda6519e2b","n":191,"o":"191-6","u":"Identifier une urgence","t":"Reconnaître le caractère urgent de la prise en charge thérapeutique d’une neutropénie fébrile et d’un patient immunodéprimé fébrile","q":"Quelle doit être la conduite thérapeutique initiale face à une neutropénie fébrile ?","a":"<p>La conduite thérapeutique initiale est l'instauration d'une <strong>antibiothérapie probabiliste bactéricide</strong> dans l'<strong>heure qui suit</strong> la réalisation des prélèvements (notamment des hémocultures), et ce, sans attendre les résultats. Cette antibiothérapie doit être débutée même sans certitude d'une infection bactérienne.</p>"},{"i":"c2615816e5fa","n":191,"o":"191-6","u":"Identifier une urgence","t":"Reconnaître le caractère urgent de la prise en charge thérapeutique d’une neutropénie fébrile et d’un patient immunodéprimé fébrile","q":"Pourquoi la neutropénie fébrile est-elle considérée comme une urgence diagnostique et thérapeutique ?","a":"<p>La neutropénie fébrile est considérée comme une urgence car elle est <strong>d'origine infectieuse jusqu'à preuve du contraire</strong>. Une infection non traitée, notamment une bactériémie à <em>Pseudomonas aeruginosa</em>, peut entraîner une mortalité très élevée (<strong>60% à 24h</strong>) chez le patient neutropénique.</p>"}]};